"""Self-generation end to end  (R-02.5; AC-002.3's F2 share, AC-002.4, AC-002.15).

Through **F4's real in-process provider over its fake handle** (no card, no sibling) and
**F3's real rule selector**, so the identity-capture path and the verdict path both run for
real. A stub provider returning a hand-built ``ProviderIdentity`` would make the
``resolved_model`` assertion agree with itself, which is the fixture failure ADR-016 names.

The three things this source must get right, and why each is here:

* **the resolved generating model on every batch** - *candidates generated by two different
  models are not interchangeable*, and on the in-process path the **step** is part of the
  answer, because the parameters move every step;
* **the three verdict counts** - an ``undecided`` is never admitted and never counted as a
  rejection;
* **a refusal refuses the whole batch** - a provider outage is not a training signal.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

import pytest

from core.errors import Refusal
from providers.base import GenerationParams
from tests.support import db as support_db
from tests.support import signal_fixtures as fixtures
from training.signals import batch_index, ensure_registered, registry
from training.signals.base import PartSpec, RunContext, SourceSpec
from training.signals.settings import reset_signal_settings


@pytest.fixture
def engine(tmp_path: Path) -> Any:
    engine = support_db.migrated_engine(tmp_path / "db")
    return engine


@pytest.fixture(autouse=True)
def _settings(monkeypatch: pytest.MonkeyPatch) -> Any:
    monkeypatch.setenv("SIGNAL_SFT_MASKING_POLICY", "completion_only")
    monkeypatch.setenv("SIGNAL_PENDING_SHORTFALL", "short_batch")
    reset_signal_settings()
    yield
    reset_signal_settings()


def build(
    session: Any,
    tmp_path: Path,
    *,
    prompts: list[str],
    answers: Any = "a good answer",
    provider: Any | None = None,
    step: int = 12,
    batch_size: int = 2,
    **context: Any,
) -> Any:
    part = fixtures.prompt_part(session, tmp_path, prompts=prompts)
    ensure_registered()
    source = registry.get("self-generation")(
        RunContext(
            run_id="run-1",
            session=session,
            provider=provider or fixtures.in_process_provider(answers),
            current_step=lambda: step,
            tokenizer=fixtures.FakeTokenizer(),
            **context,
        )
    )
    source.preflight(
        SourceSpec(
            source="self-generation",
            parts=(PartSpec(kind="prompt_set", part_id=str(part["id"])),),
            selector=fixtures.rule_selector(forbidden=("boilerplate",)),
            config_source="inline",
            batch_size=batch_size,
            params=GenerationParams(max_tokens=16),
        )
    )
    return source


class TestTheGeneratingIdentity:
    def test_every_batch_records_which_model_produced_the_candidates(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """R-02.8's third clause, FR-002.11. The **step** is part of the in-process
        identity: the parameters move every step, so candidates from step 12 are not
        candidates from step 13."""
        with support_db.session_for(engine) as session:
            source = build(session, tmp_path, prompts=["q1", "q2"], step=12)
            batch = source.next()
        assert batch.record["resolved_model"] == "in_process:fake-model@12"
        assert batch.provider.kind == "in_process"
        assert batch.provider.base_url is None

    def test_the_identity_is_captured_from_the_reply_not_from_the_configuration(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """A configured model name is what was asked for; the reply says what answered."""
        from providers.fakes import FakeProvider

        provider = FakeProvider(kind="openai_compatible", model="llama-3", base_url="http://x:8000")
        with support_db.session_for(engine) as session:
            source = build(session, tmp_path, prompts=["q1", "q2"], provider=provider)
            batch = source.next()
        assert batch.record["resolved_model"] == "openai_compatible:llama-3@http://x:8000"

    def test_two_models_answering_one_batch_is_refused(self, engine: Any, tmp_path: Path) -> None:
        """A batch record carries one ``resolved_model``; recording either would be a claim
        about candidates the other produced."""
        from providers.base import Completion, ProviderIdentity

        class TwoModels:
            identity = ProviderIdentity(kind="in_process", model="a")

            def available(self) -> bool:
                return True

            def generate(self, prompts: list[str], params: Any, **options: Any) -> list[Any]:
                return [
                    Completion(
                        text="answer",
                        provider=ProviderIdentity(kind="in_process", model=f"model-{index}"),
                        params=params,
                    )
                    for index, _prompt in enumerate(prompts)
                ]

        with support_db.session_for(engine) as session:
            source = build(session, tmp_path, prompts=["q1", "q2"], provider=TwoModels())
            with pytest.raises(Refusal) as caught:
                source.next()
        assert caught.value.code == "generating_identity_ambiguous"


class TestSelection:
    def test_only_accepted_completions_become_training_examples(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """R-02.5: the selector decides, and the rejected answer is not in the batch."""
        answers = iter(["a good answer", "boilerplate filler"])
        with support_db.session_for(engine) as session:
            source = build(
                session,
                tmp_path,
                prompts=["q1", "q2"],
                answers=lambda prompt, index: next(answers),
            )
            batch = source.next()
        assert [example.completion for example in batch.examples] == ["a good answer"]
        assert batch.record["verdicts"] == {"accept": 1, "reject": 1, "undecided": 0}

    def test_the_health_record_rides_on_the_batch_with_its_sample_size(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """FR-002.15 / ADR-012: the acceptance rate never travels without its ``n``."""
        with support_db.session_for(engine) as session:
            source = build(session, tmp_path, prompts=["q1", "q2"])
            batch = source.next()
        assert batch.health is not None
        assert batch.health.n == 2
        assert batch.record["selection_health"]["candidates_generated"] == 2
        assert batch.record["selection_health"]["acceptance_rate"] == 1.0

    def test_a_selector_that_accepts_everything_is_named_on_the_batch(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """One of the three degenerate signals F6 stops on. The names are F3's, carried
        rather than coined - a second spelling is a signal that fires and is never seen."""
        with support_db.session_for(engine) as session:
            source = build(session, tmp_path, prompts=["q1", "q2", "q3", "q4", "q5"], batch_size=5)
            batch = source.next()
        assert "selection_accepts_everything" in batch.health.signal_names

    def test_the_selector_hash_and_its_provenance_come_from_f3(
        self, engine: Any, tmp_path: Path
    ) -> None:
        with support_db.session_for(engine) as session:
            source = build(session, tmp_path, prompts=["q1", "q2"])
            batch = source.next()
        assert batch.record["selector_config_sha256"] == batch.hashes.selector_hash
        # The provenance has **no field in the gate contract**, so it rides on the batch for
        # F5's manifest write. Reported as owed; never defaulted to "contract".
        assert batch.hashes.selector_hash_provenance == "local"

    def test_an_empty_completion_is_rejected_and_never_admitted(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """E-9: a zero-length supervised example contributes nothing and dilutes the batch
        it is counted in."""
        answers = iter(["a good answer", "   "])
        with support_db.session_for(engine) as session:
            source = build(
                session, tmp_path, prompts=["q1", "q2"], answers=lambda prompt, index: next(answers)
            )
            batch = source.next()
        assert len(batch.examples) == 1
        assert batch.record["verdicts"]["reject"] == 1
        assert batch.record["verdicts"]["undecided"] == 0


class TestRefusalsRefuseTheWholeBatch:
    def test_a_generation_failure_refuses_the_batch_and_substitutes_nothing(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """E-6: a provider outage is not a training signal."""

        class Broken:
            identity = fixtures.in_process_provider().identity

            def available(self) -> bool:
                return True

            def generate(self, prompts: list[str], params: Any, **options: Any) -> list[Any]:
                raise RuntimeError("connection reset")

        with support_db.session_for(engine) as session:
            source = build(
                session,
                tmp_path,
                prompts=["q1", "q2"],
                provider=Broken(),
                log_root=tmp_path / "runs",
            )
            with pytest.raises(Refusal) as caught:
                source.next()
        assert caught.value.code == "generation_failed"
        assert not (tmp_path / "runs" / "run-1" / "run.jsonl").exists()

    def test_a_short_reply_is_refused_rather_than_joined(self, engine: Any, tmp_path: Path) -> None:
        class Short:
            identity = fixtures.in_process_provider().identity

            def available(self) -> bool:
                return True

            def generate(self, prompts: list[str], params: Any, **options: Any) -> list[Any]:
                from providers.base import Completion

                return [Completion(text="only one", provider=self.identity, params=params)]

        with support_db.session_for(engine) as session:
            source = build(session, tmp_path, prompts=["q1", "q2"], provider=Short())
            with pytest.raises(Refusal) as caught:
                source.next()
        assert caught.value.code == "generation_short_reply"

    def test_an_exhausted_prompt_set_refuses_rather_than_cycling(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """R-02.26's prompt refresh is **F6's**. A source that quietly cycled would make
        every later round train on material the model has already been fitted to."""
        with support_db.session_for(engine) as session:
            source = build(session, tmp_path, prompts=["q1", "q2"], batch_size=2)
            source.next()
            with pytest.raises(Refusal) as caught:
                source.next()
        assert caught.value.code == "prompt_set_exhausted"

    def test_a_selector_is_required_at_preflight(self, engine: Any, tmp_path: Path) -> None:
        with support_db.session_for(engine) as session:
            part = fixtures.prompt_part(session, tmp_path, prompts=["q1"])
            ensure_registered()
            source = registry.get("self-generation")(
                RunContext(run_id="run-1", session=session, provider=fixtures.in_process_provider())
            )
            with pytest.raises(Refusal) as caught:
                source.preflight(
                    SourceSpec(
                        source="self-generation",
                        parts=(PartSpec(kind="prompt_set", part_id=str(part["id"])),),
                    )
                )
        assert caught.value.code == "selector_not_configured"

    def test_an_absent_provider_refuses_at_preflight_not_at_the_first_candidate(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """R-02.48: *a run that cannot proceed says so before it starts, not partway
        through.*"""
        with support_db.session_for(engine) as session:
            part = fixtures.prompt_part(session, tmp_path, prompts=["q1"])
            ensure_registered()
            source = registry.get("self-generation")(RunContext(run_id="run-1", session=session))
            with pytest.raises(Refusal) as caught:
                source.preflight(
                    SourceSpec(
                        source="self-generation",
                        parts=(PartSpec(kind="prompt_set", part_id=str(part["id"])),),
                        selector=fixtures.rule_selector(),
                        config_source="inline",
                    )
                )
        assert caught.value.code == "generation_provider_not_configured"


class TestCancellation:
    def test_cancellation_before_generation_discards_the_batch_and_starts_no_step(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """E-20, ADR-007: a batch is assembled and recorded, or it is not handed to a step."""
        with support_db.session_for(engine) as session:
            source = build(
                session,
                tmp_path,
                prompts=["q1", "q2"],
                is_cancelled=lambda: True,
                log_root=tmp_path / "runs",
            )
            with pytest.raises(Refusal) as caught:
                source.next()
        assert caught.value.code == "batch_assembly_cancelled"
        assert not (tmp_path / "runs" / "run-1" / "run.jsonl").exists()

    def test_cancellation_between_completions_discards_the_partial_batch(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """Checked **between** completions, never inside one: a completion is generated or
        it is not started."""
        state = {"calls": 0}

        def cancelled() -> bool:
            state["calls"] += 1
            return state["calls"] > 1

        with support_db.session_for(engine) as session:
            source = build(
                session,
                tmp_path,
                prompts=["q1", "q2", "q3", "q4"],
                batch_size=4,
                is_cancelled=cancelled,
                log_root=tmp_path / "runs",
            )
            with pytest.raises(Refusal) as caught:
                source.next()
        assert caught.value.code in ("generation_cancelled", "batch_assembly_cancelled")
        assert not (tmp_path / "runs" / "run-1" / "run.jsonl").exists()


class TestThreeRounds:
    def test_three_rounds_each_produce_a_recorded_batch(self, engine: Any, tmp_path: Path) -> None:
        """**AC-002.3's F2 share** (BRD AC3): three rounds, each recording the resolved
        generating identity, the verdicts, the health record and the configuration hash.

        The full criterion - *a self-generation run with the judge-model selector over three
        rounds* - needs F4, F5 and F6 as well; what is demonstrated here is that the batches
        are real, selected and recorded.
        """
        # A holder rather than an iterator: `current_step` is asked **twice per batch** -
        # once for the generating identity and once for the run-log block's step - and a
        # callable that answered differently within one batch would attribute the
        # candidates to one step and the record to another.
        step = {"value": 1}
        with support_db.session_for(engine) as session:
            part = fixtures.prompt_part(session, tmp_path, prompts=[f"q{i}" for i in range(6)])
            ensure_registered()
            source = registry.get("self-generation")(
                RunContext(
                    run_id="run-1",
                    session=session,
                    provider=fixtures.in_process_provider(),
                    current_step=lambda: step["value"],
                    tokenizer=fixtures.FakeTokenizer(),
                    log_root=tmp_path / "runs",
                )
            )
            source.preflight(
                SourceSpec(
                    source="self-generation",
                    parts=(PartSpec(kind="prompt_set", part_id=str(part["id"])),),
                    selector=fixtures.rule_selector(),
                    config_source="inline",
                    batch_size=2,
                )
            )
            batches = []
            for round_number in (1, 2, 3):
                step["value"] = round_number
                batches.append(source.next())
            rows = batch_index.list_batches(session, run_id="run-1", limit=10)

        assert [b.record["resolved_model"] for b in batches] == [
            "in_process:fake-model@1",
            "in_process:fake-model@2",
            "in_process:fake-model@3",
        ]
        assert len({b.record["batch_sha256"] for b in batches}) == 3
        assert len(rows) == 3
        assert all(row["source"] == "self-generation" for row in rows)


class TestARoundThatAdmitsNothing:
    def test_a_batch_that_admits_nothing_is_refused_and_never_padded(
        self, engine: Any, tmp_path: Path
    ) -> None:
        """**E-7.** A round in which everything is rejected cannot fill the batch, and the
        rejected completions never make up the number.

        Refused even under ``short_batch``, because a zero-example batch is not a short
        batch: it is a step that trains on nothing while every log line looks healthy. The
        refusal carries F3's **named** signal, so the operator reads the cause - *a selector
        that rejects everything* - rather than the symptom. Stopping the run is still F6's.
        """
        with support_db.session_for(engine) as session:
            source = build(
                session,
                tmp_path,
                prompts=["q1", "q2", "q3", "q4", "q5"],
                answers="boilerplate every time",
                batch_size=5,
                log_root=tmp_path / "runs",
            )
            with pytest.raises(Refusal) as caught:
                source.next()
        assert caught.value.code == "selection_admitted_nothing"
        assert caught.value.details["rejected"] == 5
        assert caught.value.details["pending"] == 0
        assert "selection_rejects_everything" in caught.value.details["signals"]
        # Nothing was recorded: the batch was never handed to a step.
        assert not (tmp_path / "runs" / "run-1" / "run.jsonl").exists()
